<h2>Estimate warehouse space requirements</h2><p class="lead">Convert inventory units into pallet positions and gross floor area using explicit pallet, stacking and storage-efficiency assumptions.</p>
<div class="form-grid"><div class="field"><label for="units">Peak inventory units</label><input id="units" type="number" min="0" step="any" value="12000"></div><div class="field"><label for="upp">Units per pallet</label><input id="upp" type="number" min="0.0001" step="any" value="48"></div><div class="field"><label for="area">Pallet footprint (m² or ft²)</label><input id="area" type="number" min="0.0001" step="any" value="1.2"></div><div class="field"><label for="levels">Effective storage levels</label><input id="levels" type="number" min="1" step="1" value="4"></div><div class="field"><label for="storageShare">Storage footprint as % of gross warehouse area</label><input id="storageShare" type="number" min="1" max="100" step="any" value="45"></div><div class="field"><label for="buffer">Growth / peak buffer (%)</label><input id="buffer" type="number" min="0" step="any" value="15"></div></div>
<div class="result-box"><div class="result-grid"><div class="metric"><span>Buffered pallets</span><strong id="pallets">—</strong></div><div class="metric"><span>Floor positions</span><strong id="positions">—</strong></div><div class="metric"><span>Storage footprint</span><strong id="footprint">—</strong></div><div class="metric"><span>Estimated gross area</span><strong id="gross">—</strong></div></div></div>
<script>
(()=>{const $=id=>document.getElementById(id);function go(){const u=+$('units').value,upp=+$('upp').value,a=+$('area').value,l=Math.floor(+$('levels').value),s=+$('storageShare').value,b=+$('buffer').value;if(!(u>=0&&upp>0&&a>0&&l>=1&&s>0&&s<=100&&b>=0)){['pallets','positions','footprint','gross'].forEach(id=>$(id).textContent='—');return}const p=Math.ceil((u/upp)*(1+b/100)),pos=Math.ceil(p/l),fp=pos*a,g=fp/(s/100);$('pallets').textContent=p.toLocaleString();$('positions').textContent=pos.toLocaleString();$('footprint').textContent=fp.toLocaleString(undefined,{maximumFractionDigits:2})+' area units';$('gross').textContent=g.toLocaleString(undefined,{maximumFractionDigits:2})+' area units'}['units','upp','area','levels','storageShare','buffer'].forEach(id=>$(id).addEventListener('input',go));go()})();
</script>
